#include <iostream>

int main() {
    int x = 5;  // Example variable
    int y = 3;  // Another example variable

    // Problematic case without braces: else associates with the inner if
    if (x > 0)
        if (y > 0)
            std::cout << "Both x and y are positive." << std::endl;  // Inner if block
        else
            std::cout << "y is not positive." << std::endl;  // This else is for the inner if

    // Corrected case with braces: explicitly associates else with the outer if
    if (x > 0) {
        if (y > 0)
            std::cout << "Both x and y are positive (explicit)." << std::endl;
    } else {
        std::cout << "x is not positive." << std::endl;  // Now this else is for the outer if
    }

    return 0;
}
